export async function renderMapAdvanced(ctx){const {sb,content,setTitle,date}=ctx;setTitle('Mapa avançado','Calor, conversão e cancelamento por cidade');if(window.__tvAdvMap){try{window.__tvAdvMap.remove()}catch{}window.__tvAdvMap=null}const days=Number(document.getElementById('periodFilter')?.value||30);const {data:fvals}=await sb.rpc('tv_map_filter_values',{p_days:Math.max(days,365),p_base:null});content.innerHTML=`<div class="card map-filterbar"><select id="mapDays"><option value="7">7 dias</option><option value="30">30 dias</option><option value="90">90 dias</option><option value="365">12 meses</option><option value="1095">3 anos</option></select><select id="mapCity"><option value="">Todas as cidades</option><option value="natal">Natal</option><option value="fortaleza">Fortaleza</option><option value="recife">Recife</option><option value="mossoro">Mossoró</option></select><select id="mapTeam"><option value="">Todas as equipes</option></select><select id="mapConsult"><option value="">Todos os consultores</option></select><select id="mapLayer"><option value="heat">Mapa de calor</option><option value="bubble">Bolhas por volume</option><option value="conversion">Conversão por área</option><option value="cancel">Cancelamento por área</option></select><button class="primary" id="mapApply">Aplicar</button><a class="ghost" href="/consultivo.html?screen=team" id="mapTracking">Rastreamento da equipe</a><button class="ghost" id="mapLocate">Minha localização</button><span id="mapLocationStatus" class="muted">GPS do aparelho</span></div><div id="mapStats" class="stats map-stats"></div><div class="map-advanced-grid"><div class="card"><div id="salesMap" class="advanced-map"></div></div><div class="card"><h3>Ranking de áreas</h3><div id="mapRank" class="rank"></div></div></div>`;document.getElementById('mapDays').value=String(days);const teams=fvals?.teams||[],consults=fvals?.consultants||[];document.getElementById('mapTeam').insertAdjacentHTML('beforeend',teams.map(x=>`<option>${esc(x)}</option>`).join(''));document.getElementById('mapConsult').insertAdjacentHTML('beforeend',consults.map(x=>`<option>${esc(x)}</option>`).join(''));
function cityKey(v){const c=String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toUpperCase();return c==='NATAL'?'natal':c==='FORTALEZA'?'fortaleza':c==='RECIFE'?'recife':c==='MOSSORO'?'mossoro':''}
const isConsultivoApp=/TechNET-Consultivo\//.test(navigator.userAgent);let currentMap=null,deviceMarker=null,accuracyCircle=null;
function locationStatus(text,error=false){const el=document.getElementById('mapLocationStatus');if(!el)return;el.textContent=text;el.style.color=error?'#b91c1c':''}
async function devicePosition(){locationStatus('Localizando aparelho…');try{const p=await getDevicePosition();return {lat:p.latitude,lng:p.longitude,accuracy:p.accuracy}}catch(error){locationStatus(error.message,true);return null}}
function drawDeviceLocation(position,focus=false){if(!currentMap||!position)return;try{if(deviceMarker)currentMap.removeLayer(deviceMarker);if(accuracyCircle)currentMap.removeLayer(accuracyCircle)}catch{}const point=[position.lat,position.lng],accuracy=Math.max(5,position.accuracy||5);accuracyCircle=L.circle(point,{radius:accuracy,color:'#D71920',fillColor:'#D71920',fillOpacity:.08,weight:1}).addTo(currentMap);deviceMarker=L.circleMarker(point,{radius:9,color:'#ffffff',fillColor:'#D71920',fillOpacity:1,weight:3}).bindPopup(`<b>Sua localização</b><br>Precisão aproximada: ${Math.round(accuracy)}m`).addTo(currentMap);locationStatus(`Sua localização · ±${Math.round(accuracy)}m`);if(focus)currentMap.setView(point,17);else if(!currentMap.getBounds().contains(point)){const bounds=currentMap.getBounds();bounds.extend(point);currentMap.fitBounds(bounds,{padding:[28,28],maxZoom:14})}}
async function locateOnMap(focus=false){const position=await devicePosition();if(position)drawDeviceLocation(position,focus);return position}
async function load(){const p_days=Number(document.getElementById('mapDays').value),selectedCity=document.getElementById('mapCity').value,p_team_name=document.getElementById('mapTeam').value||null,p_consultant_name=document.getElementById('mapConsult').value||null,layer=document.getElementById('mapLayer').value;const {data,error}=await sb.rpc('tv_map_advanced',{p_days,p_base:null,p_team_name,p_consultant_name});if(error)throw error;const rows=(data||[]).filter(x=>!selectedCity||cityKey(x.city_name)===selectedCity),total=rows.reduce((a,x)=>a+Number(x.sales_count),0),inst=rows.reduce((a,x)=>a+Number(x.installed_count),0),cancel=rows.reduce((a,x)=>a+Number(x.cancelled_count),0),pending=rows.reduce((a,x)=>a+Number(x.pending_count),0);document.getElementById('mapStats').innerHTML=`<div class="stat"><div class="label">Vendas mapeadas</div><div class="value">${total}</div></div><div class="stat"><div class="label">Áreas</div><div class="value">${rows.length}</div></div><div class="stat"><div class="label">Instalação</div><div class="value">${total?Math.round(inst/total*100):0}%</div><div class="sub">${inst} instaladas</div></div><div class="stat"><div class="label">Cancelamento</div><div class="value">${total?Math.round(cancel/total*100):0}%</div><div class="sub">${cancel} canceladas · ${pending} pendentes</div></div>`;document.getElementById('mapRank').innerHTML=rows.slice().sort((a,b)=>Number(b.sales_count)-Number(a.sales_count)).slice(0,15).map((x,i)=>`<div class="rank-item"><div class="rank-pos">${i+1}</div><div><div class="rank-name">${esc(x.neighborhood)} · ${esc(x.city_name)}/${esc(x.state)}</div><div class="rank-sub">Inst. ${x.conversion_rate}% · Canc. ${x.cancel_rate}%</div></div><div class="rank-score">${x.sales_count}</div></div>`).join('')||'<div class="empty">Sem áreas mapeadas no filtro.</div>';if(window.__tvAdvMap){window.__tvAdvMap.remove()}const map=L.map('salesMap').setView([-5.8,-36.5],6);window.__tvAdvMap=map;currentMap=map;deviceMarker=null;accuracyCircle=null;L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(map);if(!rows.length){if(isConsultivoApp)await locateOnMap(true);return}const max=Math.max(...rows.map(x=>Number(x.sales_count)||1));if(layer==='heat'&&L.heatLayer){L.heatLayer(rows.map(x=>[Number(x.latitude),Number(x.longitude),Math.max(.15,Number(x.sales_count)/max)]),{radius:32,blur:25,maxZoom:15}).addTo(map)}else{for(const x of rows){const conv=Number(x.conversion_rate),can=Number(x.cancel_rate),n=Number(x.sales_count),metric=layer==='cancel'?can:layer==='conversion'?conv:n/max*100,color=layer==='cancel'?(metric>=40?'#dc2626':metric>=20?'#f59e0b':'#16a34a'):(layer==='conversion'?(metric>=70?'#16a34a':metric>=40?'#f59e0b':'#dc2626'):'#2563eb');L.circleMarker([Number(x.latitude),Number(x.longitude)],{radius:Math.min(30,7+Math.sqrt(n)*3),color,fillColor:color,fillOpacity:.55,weight:2}).bindPopup(`<b>${esc(x.neighborhood)} · ${esc(x.city_name)}/${esc(x.state)}</b><br>${n} vendas<br>${x.installed_count} instaladas · ${x.cancelled_count} canceladas · ${x.pending_count} pendentes<br>Instalação: ${x.conversion_rate}% · Cancelamento: ${x.cancel_rate}%<br><small>Última: ${date(x.last_sale)}</small>`).addTo(map)}}const bounds=rows.map(x=>[Number(x.latitude),Number(x.longitude)]);map.fitBounds(bounds,{padding:[28,28],maxZoom:14});setTimeout(()=>map.invalidateSize(),50);if(isConsultivoApp)await locateOnMap(false)}
document.getElementById('mapApply').onclick=load;document.getElementById('mapLayer').onchange=load;document.getElementById('mapCity').onchange=load;document.getElementById('mapLocate').onclick=()=>locateOnMap(true);await load()}
export async function setupNotifications(ctx){const {sb,session,profile,toast,navigate}=ctx;if(!session?.user?.id)return;if(window.__tvNotifChannel){try{await sb.removeChannel(window.__tvNotifChannel)}catch{}}let btn=document.getElementById('notifBtn');if(!btn){btn=document.createElement('button');btn.id='notifBtn';btn.className='ghost notif-btn';btn.innerHTML='🔔<span id="notifBadge"></span>';document.querySelector('.top-actions')?.prepend(btn)}let panel=document.getElementById('notifPanel');if(!panel){panel=document.createElement('aside');panel.id='notifPanel';panel.className='notif-panel';document.body.appendChild(panel)}async function refreshBadge(){const {count}=await sb.from('tv_notifications').select('*',{count:'exact',head:true}).is('read_at',null);const b=document.getElementById('notifBadge');if(b){b.textContent=count?String(Math.min(count,99)):'';b.classList.toggle('show',!!count)}}async function openPanel(){const {data}=await sb.from('tv_notifications').select('*').order('created_at',{ascending:false}).limit(50);panel.innerHTML=`<div class="notif-head"><div><b>Notificações</b><small>TechNET Vendas</small></div><button id="notifClose" class="ghost">✕</button></div><button id="enablePush" class="notif-permission">${('Notification' in window&&Notification.permission==='granted')?'✓ Alertas do aparelho ativados':('Notification' in window?'Ativar alertas no aparelho':'Alertas do aparelho indisponíveis')}</button><div class="notif-list">${(data||[]).length?(data||[]).map(n=>`<button class="notif-item ${n.read_at?'':'unread'}" data-sale="${n.sale_id||''}"><b>${esc(n.title)}</b><span>${esc(n.body)}</span><small>${fmt(n.created_at)}</small></button>`).join(''):'<div class="empty">Nenhuma notificação.</div>'}</div>`;panel.classList.add('open');document.getElementById('notifClose').onclick=()=>panel.classList.remove('open');document.getElementById('enablePush').onclick=async()=>{if('Notification'in window){const p=await Notification.requestPermission();toast(p==='granted'?'Alertas ativados':'Permissão não concedida');openPanel()}};document.querySelectorAll('.notif-item').forEach(x=>x.onclick=async()=>{panel.classList.remove('open');const saleId=x.dataset.sale;if(!saleId)return;const role=profile?.role;if(role==='backoffice'){localStorage.setItem('tv_bo_sale_focus',saleId);await navigate('backoffice');return}localStorage.setItem('tv_sales_focus',JSON.stringify({type:'sale',name:'Venda da notificação',id:saleId}));await navigate(role==='consultant'?'my-sales':'team')});await sb.from('tv_notifications').update({read_at:new Date().toISOString()}).is('read_at',null);refreshBadge()}
btn.onclick=openPanel;window.__tvNotifChannel=sb.channel('tv-notifications-'+session.user.id).on('postgres_changes',{event:'INSERT',schema:'public',table:'tv_notifications',filter:`user_id=eq.${session.user.id}`},payload=>{const n=payload.new;toast(n.title||'Nova notificação');refreshBadge();if('Notification'in window&&Notification.permission==='granted')new Notification(n.title||'TechNET Vendas',{body:n.body||''})}).subscribe();await refreshBadge()}

